from __future__ import absolute_import
import re

from robot.api import logger

from .files_listing import FilesListing


class MemDumps(object):
    """

    """

    def __init__(self):
        self.abia_l_map = {'2': '1',
                           '3': '2',
                           '4': '3',
                           '5': '4',
                           '6': '5'}

        self.abia_r_map = {'2': '5',
                           '3': '6',
                           '4': '7',
                           '5': '8',
                           '6': '9'}

        self.dsp_map = {'3': 'A',
                        '4': 'B',
                        '5': 'C',
                        '6': 'D'}

        self.dsp_core_max_nr = {'ASIB': 8,
                                'ASIA': 8,
                                'ASIL': 8,
                                'FSMF': 4}

    def get_bbu_id_on_which_dsp_crashed(self, all_files_list, pattern):
        """
        Keyword for getting list of FSPs on which DSP crashed

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+------------------------------+
        | Input Parameters   | Man.   | Description                  |
        +====================+========+==============================+
        | all_files_list     | Yes    | List of files to check       |
        +--------------------+--------+------------------------------+
        | pattern            | Yes    | Pattern to find memory dumps |
        +--------------------+--------+------------------------------+

        | **Return value:**
        | List of BB units on which DSP crash already happened
        """
        prev_bbu_id = set()
        mem_dump_files = FilesListing.parse_files_list(all_files_list, pattern)
        if len(mem_dump_files) > 0:
            for file_name, file_attrs in mem_dump_files:
                bbu_id = self.get_bbu_id_from_dsp_id(file_attrs[0])
                prev_bbu_id.add(bbu_id)
        return sorted(prev_bbu_id)

    def build_diagn_path_for_rel4(self, dsp_id_stripped):
        """
        Keyword for creating path to memory dump files on AirScale for SM ASIB, ASIA or ASIL

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Creates path to memory dump files on AirScale.
        | Path is different for each ABIA and DSP. Moreover,
        | path is different for left/right position
        | of the AirScale module.

        **Input Parameters:**

        +--------------------+--------+-------------------------+
        | Input Parameters   | Man.   | Description             |
        +====================+========+=========================+
        | dsp_id_stripped    | Yes    | DSP_ID already stripped |
        +--------------------+--------+-------------------------+

        | **Return value:**
        | Path to memory dump files on AirScale.
        """

        asia_side, abia_nr, dsp_nr = self.get_bbu_id_from_dsp_id(
            dsp_id_stripped, True)

        if int(asia_side) == 1:
            return "/ffs/run/logs/" + self.abia_l_map[abia_nr] + "/" + \
                   self.dsp_map[dsp_nr]
        elif int(asia_side) == 2:
            return "/ffs/run/logs/" + self.abia_r_map[abia_nr] + "/" + \
                   self.dsp_map[dsp_nr]
        else:
            logger.info("SM side unsupported")

    @staticmethod
    def get_bbu_id_from_dsp_id(dsp_id, rel4=False):
        """
        Keyword for getting BBU_ID for given dspi_ip

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+------------------------+
        | Input Parameters   | Man.   | Description            |
        +====================+========+========================+
        | dsp_id             | Yes    | DSP Id                 |
        +--------------------+--------+------------------------+
        | rel4               | No     | Default value is False |
        +--------------------+--------+------------------------+

        **Example1:**

        .. code-block:: robotframework

            Get bbu id from dsp id  dsp_id=1231
            # This will return value: 120

        **Example2:**

        .. code-block:: robotframework

            Get bbu id from dsp id  dsp_id=1231  rel4=True
            # This will return value: ("2", "3")

        | **Return value:**
        | Parent BBU Id
        """
        if rel4:
            return dsp_id[0], dsp_id[1], dsp_id[2]
        else:
            return dsp_id[0:2] + "0"

    def create_dictionary_of_mandatory_files(self, all_files_list, dsp_id,
                                             dsp_rt_pattern, dsp_md_pattern,
                                             bts_id, sm_variant, add_prefix=True):
        """
        Keyword for creating dictionary containing
        mandatory files for memory dump

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+-------------------------------------------------+
        | Input Parameters   | Man.   | Description                                     |
        +====================+========+=================================================+
        | all_files_list     | Yes    | List of files to check                          |
        +--------------------+--------+-------------------------------------------------+
        | dsp_id             | Yes    | Id of DSP to check                              |
        +--------------------+--------+-------------------------------------------------+
        | dsp_rt_pattern     | Yes    | RT pattern for files to search                  |
        +--------------------+--------+-------------------------------------------------+
        | dsp_md_pattern     | Yes    | MD pattern for files to search                  |
        +--------------------+--------+-------------------------------------------------+
        | bts_id             | Yes    | BTS ID                                          |
        +--------------------+--------+-------------------------------------------------+
        | sm_variant         | Yes    | SMOD variant ("ASIA", "ASIB", "ASIL" or "FSMF") |
        +--------------------+--------+-------------------------------------------------+
        | add_prefix         | No     | default = True                                  |
        +--------------------+--------+-------------------------------------------------+

        | **Return value:**
        | Dictionary containing mandatory MD and RT files
        """
        mandatory_files_dict = {}
        found_md_files = []
        found_rt_files = []
        max_core = self.dsp_core_max_nr[sm_variant]
        sm_side = dsp_id[0]

        for core_id in range(1, max_core + 1):
            temp_found_files = self._verify_files(all_files_list, dsp_md_pattern.format(dsp_id[0:3], str(core_id)))
            found_md_files = found_md_files + temp_found_files

        temp_found_files = self._verify_files(all_files_list, dsp_rt_pattern.format(dsp_id[0:2]))

        found_rt_files = found_rt_files + temp_found_files

        rt_files_with_prefixes = self.add_prefix_to_filenames(found_rt_files, bts_id, sm_variant, sm_side)

        if add_prefix:
            md_files_with_prefixes = self.add_prefix_to_filenames(found_md_files, bts_id, sm_variant, sm_side)
            mandatory_files_dict["mandatory_file"] = md_files_with_prefixes + rt_files_with_prefixes
        else:
            found_md_files = ['\d*_{name}'.format(name=name) for name in found_md_files]
            mandatory_files_dict["mandatory_file"] = found_md_files + rt_files_with_prefixes

        mandatory_files_dict["not_mandatory_file"] = []

        return mandatory_files_dict

    @staticmethod
    def add_prefix_to_filenames(all_files_list, bts_id, sm_variant, sm_side):
        """
        Keyword for decorating filenames to make them acceptable by snapshot

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Adds prefix to every filename in the given list.
        | Prefix is necessary when checking files in snapshot,
        | where all files names match pattern "BTSxxxxx_1011_*"

        **Input Parameters:**

        +--------------------+--------+-------------------------------------------------+
        | Input Parameters   | Man.   | Description                                     |
        +====================+========+=================================================+
        | all_files_list     | Yes    | List of files                                   |
        +--------------------+--------+-------------------------------------------------+
        | bts_id             | Yes    | BTS ID                                          |
        +--------------------+--------+-------------------------------------------------+
        | sm_variant         | Yes    | SMOD variant ("ASIA", "ASIB", "ASIL"  or "FSMF")|
        +--------------------+--------+-------------------------------------------------+
        | sm_side            | Yes    | Side of SMOD (1:"left" or 2:"right")            |
        +--------------------+--------+-------------------------------------------------+

        | **Return value:**
        | List of files with added prefix to all of them.
        """
        tmp_all_files_list = []
        if sm_variant in ("ASIA", "ASIB", "ASIL", "FSMF") and sm_side == "2":
            node_id = "_2011_"
        else:
            node_id = "_1011_"
        for filename in all_files_list:
            new_file = "BTS" + bts_id + node_id + filename
            tmp_all_files_list.append(new_file)
        return tmp_all_files_list

    @staticmethod
    def get_bts_id(testline_name):
        """
        Keyword for getting bts_if from testline_name

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | testline_name      | Yes    | Testline name in convention:          |
        |                    |        | SBTS_14258_Surykatka                  |
        +--------------------+--------+---------------------------------------+

        | **Return value:**
        | BTS ID
        """
        pattern = r"^SBTS_(\d{5})_\w+$"
        m = re.search(pattern, testline_name)
        if m:
            bts_id = m.group(1)
            return bts_id

    @staticmethod
    def dsp_id_strip(dsp_id):
        """
        Keyword for stripping dsp_id

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------+
        | Input Parameters   | Man.   | Description   |
        +====================+========+===============+
        | dsp_id             | Yes    | DSP Id        |
        +--------------------+--------+---------------+

        **Example:**

        .. code-block:: robotframework

            dsp_id_strip  0x1231
            # This will return value: 1231

        | **Return value:**
        | Stripped DSP Id
        """
        return re.sub(r'\dx', '', dsp_id)

    def verify_mandatory_files(self, all_files_list, dsp_id, dsp_rt_pattern,
                               dsp_md_pattern):
        """
        Keyword for verifying if all mandatory
        RT and MD files were collected by BTS

        | **Author:** michal.kwasniewicz@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+-----------------------------------------------+
        | Input Parameters   | Man.   | Description                                   |
        +====================+========+===============================================+
        | all_files_list     | Yes    | List of all files collected by BTS            |
        +--------------------+--------+-----------------------------------------------+
        | dsp_id             | Yes    | ID of DSP from which                          |
        |                    |        | files should be collected                     |
        +--------------------+--------+-----------------------------------------------+
        | dsp_rt_pattern     | Yes    | Pattern for RT files                          |
        +--------------------+--------+-----------------------------------------------+
        | dsp_md_pattern     | Yes    | Pattern for MD files                          |
        +--------------------+--------+-----------------------------------------------+


        | **Return value:**
        | True if all mandatory files were collected by BTS, False otherwise
        """
        logger.debug(dsp_id)
        found_memory_dump_files, unmatched_memory_dump_files = \
            self._verify_memory_dump_files(all_files_list, dsp_id,
                                           dsp_md_pattern)
        found_runtime_files, unmatched_runtime_files = \
            self._verify_runtime_files(all_files_list,
                                       dsp_id,
                                       dsp_rt_pattern)
        unmatched_patterns = \
            unmatched_memory_dump_files + unmatched_runtime_files
        self._log_files(found_memory_dump_files, found_runtime_files,
                        unmatched_patterns)
        return not unmatched_patterns

    @staticmethod
    def _log_files(found_memory_dump_files, found_runtime_files,
                   unmatched_patterns):
        logger.debug("found mem dump files: {}".format(
            found_memory_dump_files + found_runtime_files))
        if unmatched_patterns:
            logger.error(
                'Didn\'t find all mandatory files, '
                'unmatched patterns list: {}'.format(
                    unmatched_patterns))
        else:
            logger.info('All files exists.')

    def _verify_memory_dump_files(self, files_list, dsp_id, dsp_md_pattern):
        unmatched = []
        formatted_dip_md_pattern = dsp_md_pattern.format(dsp_id[0:2])
        found_files = self._verify_files(files_list, formatted_dip_md_pattern)
        logger.debug(found_files)
        if not found_files:
            unmatched.append(formatted_dip_md_pattern)
        return found_files, unmatched

    def _verify_runtime_files(self, files_list, dsp_id, dsp_rt_pattern):
        formatted_dip_rt_pattern = dsp_rt_pattern.format(dsp_id[0:2])
        found_files = self._verify_files(files_list, formatted_dip_rt_pattern)
        unmatched = [formatted_dip_rt_pattern] if not found_files else []
        return found_files, unmatched

    @staticmethod
    def _verify_files(files_list, pattern):
        found_files = FilesListing.filter_files_list(files_list, pattern)
        return found_files

    @staticmethod
    def verify_additional_files(all_files_list, dsp_id, pattern):
        """
        Keyword for verifying if any additional files matching
        given pattern exists in given files list

        | **Author:** joanna.bielawska@nokia.com
        | **Maintainer:** alona.kulieshova@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | all_files_list     | Yes    | List of all files collected by BTS    |
        +--------------------+--------+---------------------------------------+
        | dsp_id             | Yes    | ID of DSP from which                  |
        |                    |        | files should be collected             |
        +--------------------+--------+---------------------------------------+
        | pattern            | Yes    | Pattern for files to search           |
        +--------------------+--------+---------------------------------------+

        | **Return value:**
        | True if all files matched to the pattern were found, False otherwise
        """
        temp_found_files = FilesListing.filter_files_list(all_files_list,
                                                          pattern.format(
                                                              dsp_id[0:2]))
        additional_files_exists = bool(temp_found_files)
        if additional_files_exists:
            logger.debug(
                "list of found additional files: {}".format(temp_found_files))
        return temp_found_files
